package cn.wenjin.admission.web;

import cn.wenjin.admission.workflow.RunRepository;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/v1/reports") public class ReportController {private final RunRepository runs;public ReportController(RunRepository r){runs=r;}@GetMapping Object list(Authentication a){return runs.reports(WebSupport.user(a).id());}@GetMapping("/{id}")Object get(Authentication a,@PathVariable String id){return runs.report(id,WebSupport.user(a).id()).orElseThrow(()->new IllegalArgumentException("报告不存在"));}@GetMapping("/{id}/evidence")Object evidence(Authentication a,@PathVariable String id){var r=runs.report(id,WebSupport.user(a).id()).orElseThrow(()->new IllegalArgumentException("报告不存在"));return Map.of("reportId",id,"datasetVersion",r.datasetVersion(),"evidence",r.evidence(),"ruleResults",r.ruleResults());}@PostMapping("/{id}/refine")Object refine(Authentication a,@PathVariable String id,@RequestBody Map<String,String> body){var r=runs.report(id,WebSupport.user(a).id()).orElseThrow(()->new IllegalArgumentException("报告不存在"));return Map.of("reportId",id,"message","请在原会话中发送调整条件，系统会保留数据版本并重跑受影响的推荐阶段。","currentVersion",r.version());}}

